const T14_M_M2H: SatQuestion[] = [
  { id: "t14m2h-1", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² − 64 = 0 and x > 0, what is the value of x?", type: "grid", gridAnswers: ["8"], explanation: "Goal: solve the quadratic for the positive root. Add 64: x² = 64, so x = ±8. Since x > 0, x = 8. Check: 8² − 64 = 64 − 64 = 0. The trap is reporting −8 or forgetting the positive constraint." },
  { id: "t14m2h-2", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 2x + 3y = 18 and x − 3y = 0, what is the value of x?", type: "mcq", choices: ["6", "9", "3", "12"], correct: 0, explanation: "Goal: solve the system for x. Add the two equations to cancel y: (2x + 3y) + (x − 3y) = 18 + 0 gives 3x = 18, so x = 6. Check: x − 3y = 0 gives y = 2, and 2(6) + 3(2) = 18. The trap is subtracting the equations, which would not eliminate y." },
  { id: "t14m2h-3", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 4^x = 64, what is the value of x?", type: "mcq", choices: ["3", "16", "4", "8"], correct: 0, explanation: "Goal: solve the exponential equation. Write 64 as a power of 4: 64 = 4³. So 4^x = 4³ means x = 3. Check: 4³ = 4 × 4 × 4 = 64. The trap is dividing 64 by 4 instead of using exponents." },
  { id: "t14m2h-4", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A coat originally priced at $120 is marked up by 30%. What is the new price?", type: "mcq", choices: ["$156", "$150", "$144", "$90"], correct: 0, explanation: "Goal: find the marked-up price. The increase is 30% of 120 = 0.30 × 120 = 36, so the new price is 120 + 36 = 156. Check: 1.30 × 120 = 156. The trap is computing 30% of the wrong base or subtracting instead of adding." },
  { id: "t14m2h-5", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A right triangle has legs of length 9 and 12. What is the length of the hypotenuse?", type: "grid", gridAnswers: ["15"], explanation: "Goal: find the hypotenuse with the Pythagorean theorem. Compute c² = 9² + 12² = 81 + 144 = 225. Then c = √225 = 15. Check: 9-12-15 is a 3-4-5 triangle scaled by 3. The trap is adding the legs (9 + 12 = 21) instead of using squares." },
  { id: "t14m2h-6", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If p(x) = 3x − 2, what is the value of p(p(3))?", type: "mcq", choices: ["19", "7", "21", "11"], correct: 0, explanation: "Goal: evaluate the composition. First p(3) = 3(3) − 2 = 7. Then p(7) = 3(7) − 2 = 21 − 2 = 19. Check: substitute the inner result into p before stopping. The trap is reporting the inner value 7 as the answer." },
  { id: "t14m2h-7", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 3x + 2y = 12 and x = y + 1, what is the value of y?", type: "grid", gridAnswers: ["1.8", "9/5"], explanation: "Goal: solve the system by substitution. Replace x with y + 1: 3(y + 1) + 2y = 12, so 3y + 3 + 2y = 12, giving 5y + 3 = 12. Then 5y = 9 and y = 9/5 = 1.8. Check: x = 2.8, and 3(2.8) + 2(1.8) = 8.4 + 3.6 = 12. The trap is forgetting to distribute the 3 across (y + 1)." },
  { id: "t14m2h-8", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "The parabola y = x² − 8x + 7 has its vertex at (h, k). What is the value of h?", type: "mcq", choices: ["4", "−4", "8", "7"], correct: 0, explanation: "Goal: find the x-coordinate of the vertex. Use h = −b/(2a) with a = 1 and b = −8: h = −(−8)/(2·1) = 8/2 = 4. Check: the axis of symmetry of x² − 8x + 7 is x = 4. The trap is dropping the negative sign and getting −4." },
  { id: "t14m2h-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "In a right triangle, the acute angle θ has cos θ = 8/17. What is sin θ?", type: "mcq", choices: ["15/17", "8/15", "17/15", "15/8"], correct: 0, explanation: "Goal: find sin θ from cos θ. The triangle has adjacent 8 and hypotenuse 17, so the opposite is √(17² − 8²) = √(289 − 64) = √225 = 15. Thus sin θ = 15/17. Check: 8-15-17 is a Pythagorean triple. The trap is using 8/15 (a tangent-like ratio) instead of opposite over hypotenuse." },
  { id: "t14m2h-10", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² + bx + 25 is a perfect square trinomial and b > 0, what is the value of b?", type: "mcq", choices: ["10", "5", "25", "50"], correct: 0, explanation: "Goal: match a perfect square. A perfect square is (x + a)² = x² + 2ax + a²; here a² = 25 so a = 5, and the middle term is 2a = 10. Thus b = 10. Check: (x + 5)² = x² + 10x + 25. The trap is taking b = 5 instead of doubling a." },
  { id: "t14m2h-11", section: "math", domain: "Algebra", difficulty: "hard", prompt: "A line has slope −3 and passes through (2, 5). What is its y-intercept?", type: "mcq", choices: ["11", "−3", "5", "8"], correct: 0, explanation: "Goal: find b in y = mx + b. Substitute the point: 5 = −3(2) + b, so 5 = −6 + b, giving b = 11. Check: y = −3x + 11 passes through (2, 5) since −6 + 11 = 5. The trap is sign-mishandling −3(2) and getting b = −1." },
  { id: "t14m2h-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "After a 25% discount, a tablet costs $360. What was the original price?", type: "mcq", choices: ["$480", "$450", "$432", "$385"], correct: 0, explanation: "Goal: reverse a discount. Paying after 25% off means paying 75%, so 0.75 × original = 360. Then original = 360 / 0.75 = 480. Check: 25% of 480 is 120, and 480 − 120 = 360. The trap is adding 25% of 360 back instead of dividing by 0.75." },
  { id: "t14m2h-13", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If f(x) = x² and f(a) = 81 with a < 0, what is the value of a?", type: "grid", gridAnswers: ["-9"], explanation: "Goal: find the negative root. a² = 81 gives a = ±9, and since a < 0, a = −9. Check: (−9)² = 81. The trap is reporting +9 and ignoring the a < 0 condition." },
  { id: "t14m2h-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A cylinder has radius 4 and height 6. What is its volume, in terms of π?", type: "mcq", choices: ["96π", "48π", "24π", "144π"], correct: 0, explanation: "Goal: find the cylinder volume. V = πr²h = π(4²)(6) = π(16)(6) = 96π. Check: square the radius first (16), then multiply by the height (96). The trap is using r instead of r², giving 24π." },
  { id: "t14m2h-15", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 1/x + 1/4 = 1, what is the value of x?", type: "grid", gridAnswers: ["1.333", "4/3"], explanation: "Goal: solve for x. Subtract: 1/x = 1 − 1/4 = 3/4. Taking reciprocals, x = 4/3 ≈ 1.333. Check: 1/(4/3) = 3/4, and 3/4 + 1/4 = 1. The trap is forgetting to invert 3/4 to get x." },
  { id: "t14m2h-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "What is the product of the solutions to x² − 7x + 10 = 0?", type: "mcq", choices: ["10", "7", "−10", "1"], correct: 0, explanation: "Goal: multiply the two roots. Factor: x² − 7x + 10 = (x − 2)(x − 5), so the roots are 2 and 5 and the product is 10. Check: for ax² + bx + c, the product of roots equals c/a = 10/1 = 10. The trap is confusing product with sum (which is 7)." },
  { id: "t14m2h-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "The ratio of pens to pencils in a box is 2:7. If there are 36 items total, how many are pencils?", type: "mcq", choices: ["28", "8", "21", "18"], correct: 0, explanation: "Goal: split a total by a ratio. The parts total 2 + 7 = 9, so each part is 36/9 = 4. Pencils take 7 parts: 7 × 4 = 28. Check: pens = 2 × 4 = 8, and 8 + 28 = 36. The trap is using the wrong part count for pencils." },
  { id: "t14m2h-18", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "Two similar triangles have a scale factor of 1:4. If the smaller has area 3, what is the area of the larger?", type: "mcq", choices: ["48", "12", "24", "16"], correct: 0, explanation: "Goal: scale an area by similarity. Area scales by the square of the linear ratio: 4² = 16. So the larger area is 3 × 16 = 48. Check: linear ×4 means area ×16, giving 48. The trap is multiplying the area by 4 instead of by 16." },
  { id: "t14m2h-19", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If √(x + 5) = 6, what is the value of x?", type: "mcq", choices: ["31", "1", "11", "41"], correct: 0, explanation: "Goal: solve the radical equation. Square both sides: x + 5 = 36. Subtract 5: x = 31. Check: √(31 + 5) = √36 = 6. The trap is forgetting to square the 6 or subtracting before squaring." },
  { id: "t14m2h-20", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 5x − 4y = 26 and y = 4, what is the value of x?", type: "mcq", choices: ["8.4", "6", "7", "9"], correct: 0, explanation: "Goal: solve for x after substituting y. Replace y: 5x − 16 = 26. Add 16: 5x = 42. Divide by 5: x = 42/5 = 8.4. Check: 5(8.4) − 16 = 42 − 16 = 26. The trap is forgetting that 4y = 16, not 4." },
  { id: "t14m2h-21", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If g(x) = x² − 6x + 9, for what value of x does g(x) = 0?", type: "mcq", choices: ["3", "−3", "9", "6"], correct: 0, explanation: "Goal: find the root. Factor the perfect square: x² − 6x + 9 = (x − 3)², which equals 0 only when x − 3 = 0, so x = 3. Check: 3² − 6(3) + 9 = 9 − 18 + 9 = 0. The trap is expecting two distinct roots from a perfect square." },
  { id: "t14m2h-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A population of bacteria triples every hour. If it starts at 40, how many are there after 3 hours?", type: "mcq", choices: ["1080", "360", "120", "3240"], correct: 0, explanation: "Goal: apply exponential growth. After 3 hours the count is 40 × 3³ = 40 × 27 = 1080. Check: 40 → 120 → 360 → 1080 over the three hours. The trap is multiplying by 3 only once (giving 120) instead of cubing." },
];

